def reverse_prefixes(s):
    n = len(s)
    result = [0] * n
    min_char = s[0]
    min_index = 0

    for i in range(1, n):
        if s[i] < min_char:
            min_char = s[i]
            min_index = i
        elif s[i] > min_char:
            for j in range(min_index + 1):
                result[j] = 1
            min_char = s[i]
            min_index = i

    # Reverse the last part if needed
    if min_index != n - 1:
        for j in range(min_index + 1):
            result[j] = 1

    return result

